  "settings.modelProvider.help.contextWindow": "A modell egyszerre feldolgozható kontextuskapacitása tokenben. A ZAICODE ezt használja a kontextus kezeléséhez.\nNe lépj túl a modell tényleges korlátján.",
  "settings.modelProvider.help.maxOutputTokens": "Egyetlen modellkérés által legtöbb generálható token száma.\nNe lépj túl a modell tényleges korlátján.",
  "settings.modelProvider.help.inputModalities": "Állítsd be a modell által fogadható tartalomtípusokat:\n\n- **Szöveg**: Szöveges tartalmat fogad. Kötelező.\n- **Képek**: Képtartalmat fogad.\n- **Videó**: Videótartalmat fogad.\n- **PDF**: PDF-dokumentumokat fogad közvetlenül.",
  "settings.modelProvider.help.outputModalities": "A modell válaszainak tartalomtípusa. Jelenleg csak a szöveg támogatott.",
  "settings.modelProvider.help.capabilities": "- **Strukturált kimenet**: JSON Schema-korlátok támogatása a kimeneti mezőkre, típusokra és struktúrára.\n- **Natív webes keresés**: A modell API beépített webes keresési képességének támogatása.\n- **Beszélgetés közbeni rendszerüzenetek**: Rendszerutasítások beszúrásának támogatása a beszélgetés közben.\n\nNe kapcsolj be olyan képességeket, amelyeket a modell nem támogat.",
  "settings.modelProvider.help.reasoningLevelsOrdered": "Állítsd be a chatben elérhető gondolkodási szinteket. **Alacsonytól a legmagasabb gondolkodási erőfeszítésig kell rendezni őket**.\nNe konfigurálj gondolkodási szinteket, amelyeket a modell nem támogat.",
  "settings.modelProvider.help.reasoningLevelMapping": "Egy CEL kifejezéssel képezd le az aktuális `reasoningLevel` értéket a modell API kérési mezőire. A kifejezés által visszaadott JSON objektum bekerül a kiküldött kérés törzsébe.",
  "settings.modelProvider.help.advanced": "**MFJS eszközséma**: Bekapcsolja a Moonshot Flavored JSON Schema kompatibilitást, amelyet általában a Moonshot Kimi modell API használ. Csak akkor kapcsold be, ha a modell API megköveteli ezt a formátumot.",
  "settings.modelProvider.help.followRecommendedConfig": "A modellazonosító, a Base URL és az API-formátum alapján egyezik az ajánlott konfigurációval. A ZAICODE folyamatosan frissíti az ajánlásokat, és automatikusan szinkronizálja őket.\nHa egy beállítást kézzel módosítasz, az adott beállítás kézi kezelésűvé válik, és nem követi többé az ajánlás frissítéseit; a többi beállítást továbbra is az intelligens konfiguráció kezeli.",
